import { hideChartPopover, showChartPopover } from "../chart-board/board-util";

const getPatternIndex = (id, userConfig) => {
	const keys = Array.isArray(userConfig?.keys) ? userConfig.keys : [];
	const index = keys.findIndex((key) => String(key) === String(id));

	return index < 0 ? 0 : (index % 12) + 1;
};

const getPopoverIndicator = (obj, row, color, categorical, userConfig) => {
	const id = row?.id ?? obj?.id ?? obj?.data?.id;
	const patternIndex =
		categorical && userConfig?.pattern ? getPatternIndex(id, userConfig) : 0;
	const className = [
		"chart-bar__popover-indicator",
		patternIndex > 1 ? "chart-bar__popover-indicator--pattern" : "",
		patternIndex > 1
			? `chart-bar__popover-indicator--pattern-${patternIndex}`
			: "",
	]
		.filter(Boolean)
		.join(" ");
	const indicatorStyle = categorical
		? "border-radius:var(--viz-bar-categorical-popover-indicator-border-radius, 2px);"
		: "";

	return `<div class="${className}" style="background:${color};${indicatorStyle}"></div>`;
};

function generateTooltipContentRow(obj, categorical = false, userConfig?) {
	const popoverClassName = categorical
		? "chart-bar__popover chart-bar__popover--categorical"
		: "chart-bar__popover";
	let infoBlock = null;
	if (Array.isArray(obj.data)) {
		infoBlock = obj.data
			.map(
				(r) =>
					`<div class="${popoverClassName}">
        <div>
          ${getPopoverIndicator(
						obj,
						r,
						r.color || obj.color,
						categorical,
						userConfig,
					)}
          ${r.key || r.id}
        </div>
        <div>
          ${r.formattedValue ?? r.value}
        </div>
      </div>`,
			)
			.join("");
	} else {
		infoBlock = `
      <div class="${popoverClassName}">
        <div>
          ${getPopoverIndicator(
						obj,
						undefined,
						obj.color,
						categorical,
						userConfig,
					)}
          ${obj.data.indexValue}
        </div>
        <div>
          ${obj.data.value}
        </div>
      </div>
    `;
	}
	return infoBlock;
}

const toggleBarItemPopover = (
	tooltipRef,
	event?,
	node?,
	customTooltipFunc?,
	categorical = false,
	userConfig?,
) => {
	if (event && tooltipRef) {
		showChartPopover(tooltipRef, node, event, customTooltipFunc, (data) =>
			generateTooltipContentRow(data, categorical, userConfig),
		);
	} else if (tooltipRef) {
		hideChartPopover(tooltipRef);
	}
};

const toggleBarLegendPopover = (
	tooltipRef,
	event?,
	id?: string,
	fill?: string,
	userConfig?,
	categorical = false,
) => {
	if (event && id && fill && userConfig) {
		const curDataAry = userConfig.data
			.filter((r) => Object.prototype.hasOwnProperty.call(r, id))
			.map((r) => ({
				key: r[userConfig.indexBy],
				value: r[id],
				formattedValue: r[id],
			}));

		showChartPopover(
			tooltipRef,
			{ id, data: curDataAry, color: fill },
			event,
			userConfig.legendTooltip,
			(data) => generateTooltipContentRow(data, categorical, userConfig),
		);
	} else {
		hideChartPopover(tooltipRef);
	}
};

const toggleBarMarkerLegendPopover = (
	tooltipRef,
	event?,
	legendData?,
	customTooltipFunc?,
) => {
	if (
		!event ||
		!tooltipRef ||
		!legendData ||
		typeof customTooltipFunc !== "function"
	) {
		hideChartPopover(tooltipRef);
		return;
	}

	const markerLabel =
		legendData.markerLegendLabel ?? legendData.markerValue ?? "";
	const markerValue =
		legendData.markerValue ?? legendData.markerLegendLabel ?? "";
	const fill = legendData.color || "var(--viz-color-neutral-40)";
	const stroke = legendData.lineStyle?.stroke || fill;
	const strokeWidth = Math.min(
		Number(legendData.lineStyle?.strokeWidth) || 3,
		3,
	);
	const dashArray = legendData.lineStyle?.strokeDasharray;
	const symbol = `<svg width="20" height="16" viewBox="0 0 20 16" aria-hidden="true" focusable="false">
		<rect x="0" y="2" width="20" height="12" fill="${fill}" opacity="${
			legendData.opacity ?? 1
		}"></rect>
		<line x1="0" y1="2" x2="20" y2="2" stroke="${stroke}" stroke-width="${strokeWidth}"${
			dashArray ? ` stroke-dasharray="${dashArray}"` : ""
		}></line>
	</svg>`;

	showChartPopover(
		tooltipRef,
		legendData,
		event,
		(data, tooltipEvent, h) =>
			customTooltipFunc({ ...data, markerLabel, markerValue }, tooltipEvent, h),
		() =>
			`<div class="chart-bar__popover chart-bar__popover--categorical">
				<div>${symbol}${markerLabel}</div>
				<div>${markerValue}</div>
			</div>`,
	);
};

const showBarAxisPopover = (
	data,
	event?,
	tooltipRef?,
	customTooltipFunc?,
	categorical = false,
	userConfig?,
) => {
	if (event && tooltipRef) {
		showChartPopover(tooltipRef, { data }, event, customTooltipFunc, (data) =>
			generateTooltipContentRow(data, categorical, userConfig),
		);
	} else if (tooltipRef) {
		hideChartPopover(tooltipRef);
	}
};

const hideBarPopover = (tooltipRef) => {
	hideChartPopover(tooltipRef);
};

const convertBarDataToCSV = (arr) => {
	const headers = Array.from(
		arr.reduce((total, cur) => {
			const keys = Object.keys(cur);
			keys.forEach((r) => total.add(r));
			return total;
		}, new Set()),
	) as string[];

	const title = `${headers.join(",")}\n`;

	const result = arr
		.map((it) => {
			const line = headers.reduce((total, cur, idx) => {
				let row = total + (it[cur] || '""');

				if (idx !== headers.length - 1) {
					row += ",";
				}
				return row;
			}, "");
			return line;
		})
		.join("\n");

	return title + result;
};

export {
	toggleBarItemPopover,
	toggleBarLegendPopover,
	toggleBarMarkerLegendPopover,
	showBarAxisPopover,
	hideBarPopover,
	convertBarDataToCSV,
};
