import {
	type BarDatum,
	type BarSvgProps,
	ResponsiveBar as Bar,
} from "@harbor-charts/bar";
import {
	Component,
	Element,
	Host,
	Listen,
	Method,
	Prop,
	h,
} from "@stencil/core";
import * as React from "react";
import { createRoot } from "react-dom/client";
import retargetEvents from "react-shadow-dom-retarget-events";

import { bar } from "@harbor/chart-config/bar";

const {
	getBarBaseConfig,
	getBarCategoricalConfig,
	postUpdateMergedBarConfig, //for threshold only now
	toggleBarIndividualClickingClass,
} = bar;

import merge from "deepmerge";
import {
	convertBarDataToCSV,
	hideBarPopover,
	showBarAxisPopover,
	toggleBarItemPopover,
	toggleBarLegendPopover,
	toggleBarMarkerLegendPopover,
} from "./chart-util";

import { browserDownloadCsv } from "../chart-board/board-util";
import {
	noopChartTooltip,
	omitChartConfigKeys,
} from "../chart-board/chart-config-util";
import {
	type ChartPopoverOptions,
	applyChartPopoverOptions,
	isChartPopoverSelfManaged,
	resolveChartPopoverOptions,
} from "../chart-board/popover-options";
type HbrTooltipFunction = (
	data: unknown,
	event: Event,
	h: typeof React.createElement,
) => string | object | false;

type HbrTooltipFunctions = {
	itemTooltip?: HbrTooltipFunction;
	legendTooltip?: HbrTooltipFunction;
};

type HbrBarChartConfig = Omit<Partial<BarSvgProps<BarDatum>>, "tooltip"> &
	HbrTooltipFunctions;

type ConfigWithNivoTooltip = HbrBarChartConfig & { tooltip?: unknown };

type HbrAxisTooltip = true | ((data, event, h) => string | object | false);

type HbrAxisTooltipConfig = {
	tooltip?: HbrAxisTooltip;
	popoverOptions?: ChartPopoverOptions;
	onClick?: (data, event, tick) => void;
	onMouseEnter?: (data, event, tick) => void;
	onMouseLeave?: (data, event, tick) => void;
	onMouseMove?: (data, event, tick) => void;
};

type HbrLegendPopoverConfig = {
	popoverOptions?: ChartPopoverOptions;
};

type HbrMarkerLegendPopoverConfig = {
	"marker-legend"?: HbrLegendPopoverConfig;
};

type BarAxis = "axisTop" | "axisRight" | "axisBottom" | "axisLeft";

const BAR_AXIS_PLACEMENTS: Record<BarAxis, ChartPopoverOptions["placement"]> = {
	axisTop: "top",
	axisRight: "right",
	axisBottom: "bottom",
	axisLeft: "left",
};

/**
 * @since 1.0.50
 * @status stable
 * @part chart - The chart element
 * @part header - The header element
 * @part popover-body - The popover body element, check hbr-popover for more details
 * @part popover-popup - The popover popup element,  check hbr-popover for more details
 * @part popover-arrow - The popover arrow element,  check hbr-popover for more details
 *
 * @slot header - Slot for header
 * @slot header-title - Slot for header title
 * @slot header-action - Slot for header action
 * @slot footer - Slot for footer
 * @slot loading-state - Slot for loading state
 * @slot empty-state - Slot for empty state
 * @slot content - Slot for popover content
 *
 */
@Component({
	tag: "hbr-bar-chart",
	styleUrl: "style.scss",
	shadow: true,
})
export class HbrBarChart {
	chartRef: HTMLElement;
	tooltipRef: HTMLHbrPopoverElement;
	boardRef: HTMLHbrChartBoardElement;

	/** Chart configuration object. Refer to https://nivo.rocks/bar */
	@Prop({ mutable: true }) config: HbrBarChartConfig = {
		data: [],
	};
	/** Chart width */
	@Prop() width = "100%";
	/** Chart height */
	@Prop() height = "360px";
	/** Chart loading flag */
	@Prop() loading = false;

	/** New Magnetic UX chart type */
	@Prop({ reflect: true }) categorical = false;

	/** Final config before rendering, param1 is the final config, your customization should be done here */
	@Prop() modifyHbrConfig: (
		config: HbrBarChartConfig,
		createElement: typeof React.createElement,
		util: typeof bar,
	) => ConfigWithNivoTooltip;

	/** Default popover props. Set `selfManaged` to let a categorical popover manage its own open and close behavior. */
	@Prop() popoverOptions: ChartPopoverOptions;

	@Element() private el: HTMLHbrBarChartElement;

	/** Public method for download data, use customFunc to create your own way to download data, such as pdf */
	@Method()
	async download(filename = "Export.csv", customFunc?: (data) => void) {
		if (customFunc) {
			customFunc(this.config.data);
		} else {
			browserDownloadCsv(convertBarDataToCSV(this.config.data), filename);
		}
	}

	/** Public method to get popover reference, client can use this to control magnetic UX popover externally */
	@Method()
	async getPopoverRef() {
		return this.tooltipRef;
	}

	// saved react object after it is rendered
	// this is for update since react will complain if creating root again during update
	private contextRoot = null;
	private warnedAboutNivoTooltip = false;

	private getLegendPopoverOptions() {
		return (
			this.config.legends?.[0] as unknown as HbrLegendPopoverConfig | undefined
		)?.popoverOptions;
	}

	private getMarkerLegendPopoverOptions() {
		return (this.config as HbrMarkerLegendPopoverConfig)["marker-legend"]
			?.popoverOptions;
	}

	private getPopoverOptions(
		placement: ChartPopoverOptions["placement"] = "top",
		override?: ChartPopoverOptions,
	) {
		return resolveChartPopoverOptions(
			{
				distance: this.categorical ? 4 : 10,
				variant: "chart",
				placement,
			},
			this.popoverOptions,
			this.categorical,
			override,
		);
	}

	private applyPopoverOptions(
		placement: ChartPopoverOptions["placement"] = "top",
		override?: ChartPopoverOptions,
	) {
		applyChartPopoverOptions(
			this.tooltipRef,
			this.getPopoverOptions(placement, override),
		);
	}

	private isPopoverSelfManaged(override?: ChartPopoverOptions) {
		return isChartPopoverSelfManaged(
			this.categorical,
			this.popoverOptions,
			override,
		);
	}

	componentDidLoad() {
		this.renderChart();
		retargetEvents(this.el.shadowRoot);
	}

	componentShouldUpdate() {
		return this.renderChart();
	}

	@Listen("click", { passive: true })
	handleOutsideClick(event) {
		if (this.config.isInteractive ?? true) {
			toggleBarIndividualClickingClass(event, false);
		}
	}

	renderChart = async () => {
		const configWithNivoTooltip = this.config as ConfigWithNivoTooltip;
		if (
			!this.warnedAboutNivoTooltip &&
			configWithNivoTooltip.tooltip !== undefined
		) {
			console.warn(
				"hbr-bar-chart: config.tooltip is not supported. Use itemTooltip or legendTooltip instead.",
			);
			this.warnedAboutNivoTooltip = true;
		}
		const publicConfig = omitChartConfigKeys(configWithNivoTooltip, [
			"tooltip",
		]) as HbrBarChartConfig;
		const getConfig = this.categorical
			? getBarCategoricalConfig
			: getBarBaseConfig;
		const getAxisConfig = (axis: BarAxis) =>
			(publicConfig[axis] || {}) as HbrAxisTooltipConfig;
		const getAxisTooltip = (axisConfig: HbrAxisTooltipConfig) =>
			axisConfig.tooltip === true ? undefined : axisConfig.tooltip;
		const getAxisWithTooltip = (axis: BarAxis) => {
			const axisConfig = getAxisConfig(axis);
			const tooltip = getAxisTooltip(axisConfig);
			const tooltipEnabled = !!axisConfig.tooltip;

			return {
				...((publicConfig[axis] || {}) as object),
				onClick: (data, event, tick) => {
					axisConfig.onClick?.(data, event, tick);
				},
				onMouseEnter: (data, event, tick) => {
					if (tooltipEnabled) {
						this.applyPopoverOptions(
							BAR_AXIS_PLACEMENTS[axis],
							axisConfig.popoverOptions,
						);
						showBarAxisPopover(
							data,
							event,
							this.tooltipRef,
							tooltip,
							this.categorical,
							publicConfig,
						);
					}
					axisConfig.onMouseEnter?.(data, event, tick);
				},
				onMouseLeave: (data, event, tick) => {
					if (
						tooltipEnabled &&
						!this.isPopoverSelfManaged(axisConfig.popoverOptions)
					) {
						hideBarPopover(this.tooltipRef);
					}
					axisConfig.onMouseLeave?.(data, event, tick);
				},
				onMouseMove: (data, event, tick) => {
					if (tooltipEnabled) {
						this.applyPopoverOptions(
							BAR_AXIS_PLACEMENTS[axis],
							axisConfig.popoverOptions,
						);
						showBarAxisPopover(
							data,
							event,
							this.tooltipRef,
							tooltip,
							this.categorical,
							publicConfig,
						);
					}
					axisConfig.onMouseMove?.(data, event, tick);
				},
			};
		};
		const config = this.categorical
			? {
					...publicConfig,
					...(publicConfig.axisTop
						? { axisTop: getAxisWithTooltip("axisTop") }
						: {}),
					...(publicConfig.axisRight
						? { axisRight: getAxisWithTooltip("axisRight") }
						: {}),
					axisBottom: getAxisWithTooltip("axisBottom"),
					axisLeft: getAxisWithTooltip("axisLeft"),
			  }
			: publicConfig;
		const legendPopoverOptions = this.getLegendPopoverOptions();
		const markerLegendPopoverOptions = this.getMarkerLegendPopoverOptions();
		const baseConfig = getConfig(
			config as unknown as Partial<BarSvgProps<BarDatum>>,
			{
				itemsEventHandlers: {
					onMouseEnter: (datum, event) => {
						this.applyPopoverOptions();
						toggleBarItemPopover(
							this.tooltipRef,
							event,
							datum,
							(publicConfig as HbrBarChartConfig).itemTooltip,
							this.categorical,
							publicConfig,
						);
					},
					onMouseLeave: () => {
						if (!this.isPopoverSelfManaged()) {
							toggleBarItemPopover(this.tooltipRef);
						}
					},
					onFocus: (datum, event) => {
						this.applyPopoverOptions();
						toggleBarItemPopover(
							this.tooltipRef,
							event,
							datum,
							(publicConfig as HbrBarChartConfig).itemTooltip,
							this.categorical,
							publicConfig,
						);
					},
					onBlur: () => toggleBarItemPopover(this.tooltipRef),
					onClick: (datum, event) => {
						this.applyPopoverOptions();
						toggleBarItemPopover(
							this.tooltipRef,
							event,
							datum,
							(publicConfig as HbrBarChartConfig).itemTooltip,
							this.categorical,
							publicConfig,
						);
					},
				},
				legendsEventHandlers: {
					onMouseEnter: (data, event) => {
						if ("markerValue" in data) {
							this.applyPopoverOptions("top", markerLegendPopoverOptions);
							toggleBarMarkerLegendPopover(
								this.tooltipRef,
								event,
								data,
								(publicConfig as HbrBarChartConfig).legendTooltip,
							);
							return;
						}
						if (
							data.id.toLowerCase() !== "no data" &&
							data.id.toLowerCase() !== "null"
						) {
							this.applyPopoverOptions("top", legendPopoverOptions);
							toggleBarLegendPopover(
								this.tooltipRef,
								event,
								data.id,
								data.color,
								publicConfig,
								this.categorical,
							);
						}
					},
					onMouseMove: (data, event) => {
						if ("markerValue" in data) {
							this.applyPopoverOptions("top", markerLegendPopoverOptions);
							toggleBarMarkerLegendPopover(
								this.tooltipRef,
								event,
								data,
								(publicConfig as HbrBarChartConfig).legendTooltip,
							);
						}
					},
					onMouseLeave: (data) => {
						const popoverOptions =
							"markerValue" in data
								? markerLegendPopoverOptions
								: legendPopoverOptions;
						if (!this.isPopoverSelfManaged(popoverOptions)) {
							"markerValue" in data
								? toggleBarMarkerLegendPopover(this.tooltipRef)
								: toggleBarLegendPopover(this.tooltipRef);
						}
					},
					onFocus: (data, event) => {
						if ("markerValue" in data) {
							this.applyPopoverOptions("top", markerLegendPopoverOptions);
							toggleBarMarkerLegendPopover(
								this.tooltipRef,
								event,
								data,
								(publicConfig as HbrBarChartConfig).legendTooltip,
							);
							return;
						}
						if (
							data.id.toLowerCase() !== "no data" &&
							data.id.toLowerCase() !== "null"
						) {
							this.applyPopoverOptions("top", legendPopoverOptions);
							toggleBarLegendPopover(
								this.tooltipRef,
								event,
								data.id,
								data.color,
								publicConfig,
								this.categorical,
							);
						}
					},
					onBlur: (data) =>
						"markerValue" in data
							? toggleBarMarkerLegendPopover(this.tooltipRef)
							: toggleBarLegendPopover(this.tooltipRef),
					onClick: (data, event) => {
						if ("markerValue" in data) {
							this.applyPopoverOptions("top", markerLegendPopoverOptions);
							toggleBarMarkerLegendPopover(
								this.tooltipRef,
								event,
								data,
								(publicConfig as HbrBarChartConfig).legendTooltip,
							);
							return;
						}
						if (
							data.id.toLowerCase() !== "no data" &&
							data.id.toLowerCase() !== "null"
						) {
							this.applyPopoverOptions("top", legendPopoverOptions);
							toggleBarLegendPopover(
								this.tooltipRef,
								event,
								data.id,
								data.color,
								publicConfig,
								this.categorical,
							);
						}
					},
				},
			},
		);

		const existingEventHandlers = {
			onMouseEnter: baseConfig.onMouseEnter,
			onMouseLeave: baseConfig.onMouseLeave,
			onClick: baseConfig.onClick,
			onblur: baseConfig.onBlur,
			onFocus: baseConfig.onFocus,
		};

		let fullConfig = merge(baseConfig, publicConfig, {
			arrayMerge: (_destinationArray, sourceArray) => sourceArray,
			customMerge: (key) => {
				if (key === "legends") {
					return (a, b) => {
						const ret =
							a.length > b.length
								? a.map((r, i) => ({ ...r, ...b[i] }))
								: b.map((r, i) => ({ ...a[i], ...r }));
						return ret;
					};
				}
			},
		}) as unknown as ConfigWithNivoTooltip;

		fullConfig = {
			...fullConfig,
			...existingEventHandlers,
		} as unknown as ConfigWithNivoTooltip;

		// base config adds theme as default
		// but theme may not cover every detail such as threshold line color
		// adding threshold default color/width if threshold is present
		fullConfig = postUpdateMergedBarConfig(
			fullConfig as unknown as Partial<BarSvgProps<BarDatum>>,
		) as unknown as ConfigWithNivoTooltip;
		fullConfig = omitChartConfigKeys(fullConfig, [
			"tooltip",
		]) as HbrBarChartConfig;

		if (this.modifyHbrConfig) {
			fullConfig = this.modifyHbrConfig(fullConfig, React.createElement, bar);
		}
		fullConfig = {
			...fullConfig,
			tooltip:
				(fullConfig as ConfigWithNivoTooltip).tooltip ?? noopChartTooltip,
		};
		if (!this.contextRoot) {
			this.contextRoot = createRoot(this.chartRef);
		}
		this.contextRoot.render(
			React.createElement(Bar, fullConfig as BarSvgProps<BarDatum>, null),
		);

		if (this.boardRef.setChartConfig) {
			this.boardRef.setChartConfig(fullConfig);
		}
	};

	render() {
		const layout = this.config.layout ? this.config.layout : "vertical";
		this.el.style.width = this.width;
		this.el.style.height = this.height;
		const popoverOptions = resolveChartPopoverOptions(
			{
				distance: this.categorical ? 4 : 10,
				variant: "chart",
			},
			this.popoverOptions,
			this.categorical,
		);

		return (
			<Host>
				{!this.config.data?.length && this.categorical && (
					<div slot="header" part="header" class="chart-bar__header">
						<slot name="header">
							<div>
								<slot name="header-title" />
							</div>
							<div>
								<slot name="header-action" />
							</div>
						</slot>
					</div>
				)}
				<hbr-chart-board
					type={this.categorical ? "categorical" : "bar"}
					ref={(el) => {
						this.boardRef = el;
					}}
					isLoading={this.loading}
					isEmpty={!this.config.data?.length}
					style={{
						width: this.width,
						height: this.height,
					}}
					exportparts="empty-state-illustration, empty-state-image, loading-state-illustration, loading-state-image"
				>
					<hbr-popover
						{...popoverOptions}
						ref={(el) => {
							this.tooltipRef = el;
						}}
						part="popover"
						exportparts="base__popup:popover-popup, base__arrow:popover-arrow, body:popover-body"
						anchor=""
					>
						<div slot="content" />
					</hbr-popover>
					{(this.config.data?.length || !this.categorical) && (
						<div slot="header" part="header" class="chart-bar__header">
							<slot name="header">
								<div>
									<slot name="header-title" />
								</div>
								<div>
									<slot name="header-action" />
								</div>
							</slot>
						</div>
					)}
					<div
						ref={(el) => {
							this.chartRef = el;
						}}
						class={`--hbr-chart --bar-chart --bar-${layout} ${
							this.categorical ? "--categorical" : ""
						}`}
						part="chart"
					/>
					<slot slot="footer" name="footer" />
					<slot slot="loading-state" name="loading-state" />
					<slot slot="empty-state" name="empty-state" />
				</hbr-chart-board>
			</Host>
		);
	}
}
